  string LocalVersion(){try{return File.ReadAllText(Path.Combine(Root,"installed-version.txt")).Trim();}catch{return "none";}}
  string RemoteVersion(){return Manifest!=null&&Manifest.ContainsKey("version")?Convert.ToString(Manifest["version"]):"";}
