    try{using(var wc=new WebClient()){wc.Headers[HttpRequestHeader.UserAgent]="DroidTrakr Launcher/1.0";wc.DownloadProgressChanged+=(s,e)=>Dispatcher.Invoke(delegate{Progress.Value=e.ProgressPercentage;Status.Text="DOWNLOADING  "+e.ProgressPercentage+"%";});await wc.DownloadFileTaskAsync(new Uri(Convert.ToString(Manifest["package"])),tmp);}Status.Text="VERIFYING PACKAGE";var expected=Convert.ToString(Manifest["sha256"]).ToLowerInvariant();using(var sha=SHA256.Create())using(var fs=File.OpenRead(tmp)){var actual=BitConverter.ToString(sha.ComputeHash(fs)).Replace("-","").ToLowerInvariant();if(actual!=expected)throw new Exception("Update verification failed.");}
