  void CopyTree(string source,string target){foreach(var dir in Directory.GetDirectories(source,"*",SearchOption.AllDirectories))Directory.CreateDirectory(dir.Replace(source,target));foreach(var file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){var dest=file.Replace(source,target);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(file,dest,true);}}
